uses(RefreshDatabase::class);

it('refuses to refund a cancelled order', function () {
    $order = Order::factory()->cancelled()->create();
    $fake = new FakeGateway();                                     // hand-written fake, records calls
    $this->app->instance(PaymentGateway::class, $fake);

    expect(fn () => app(RefundOrder::class)->handle($order))->toThrow(CannotRefund::class);
    expect($fake->refunds)->toBeEmpty();
    $this->assertDatabaseHas('orders', ['id' => $order->id, 'status' => 'cancelled']);
});

it('refunds a paid order and records the ledger entry', function () {
    Event::fake([OrderRefunded::class]);
    $order = Order::factory()->paid()->create(['total_minor' => 25000]);
    $this->app->instance(PaymentGateway::class, $fake = new FakeGateway());

    app(RefundOrder::class)->handle($order);

    expect($fake->refunds)->toHaveCount(1)->and($fake->refunds[0]['amount'])->toBe(25000);
    $this->assertDatabaseHas('ledger_entries', ['order_id' => $order->id, 'delta' => -25000]);
    Event::assertDispatched(OrderRefunded::class);
});

