class FakeGateway implements PaymentGateway {
    public array $refunds = []; private bool $fail = false;
    public function failNext(): void { $this->fail = true; }
    public function refund(Order $o, int $amount, string $key): RefundResult {
        if ($this->fail) { $this->fail = false; throw new GatewayException('declined'); }
        $this->refunds[] = compact('amount', 'key'); return new RefundResult('r_'.uniqid());
    }
}

it('leaves no ledger entry when the gateway fails', function () {
    $order = Order::factory()->paid()->create();
    $this->app->instance(PaymentGateway::class, $fake = new FakeGateway());
    $fake->failNext();
    expect(fn () => app(RefundOrder::class)->handle($order))->toThrow(GatewayException::class);
    $this->assertDatabaseCount('ledger_entries', 0);
    expect($order->fresh()->status)->toBe('paid');
});
